CREATE TABLE Customers (
    customer_id INT PRIMARY KEY,
    name VARCHAR(255),
    email VARCHAR(255),
    is_active BOOLEAN
);

CREATE TABLE Orders (
    order_id INT PRIMARY KEY,
    customer_id INT,
    order_date DATE,
    total_amount DECIMAL(10, 2),
    is_shipped BOOLEAN,
    FOREIGN KEY (customer_id) REFERENCES Customers(customer_id)
);

INSERT INTO Customers (customer_id, name, email, is_active) VALUES
(1, 'Alice Smith', 'alice@example.com', true),
(2, 'Bob Johnson', 'bob@example.com', true),
(3, 'Charlie Brown', 'charlie@example.com', false);

INSERT INTO Orders (order_id, customer_id, order_date, total_amount, is_shipped) VALUES
(101, 1, '2023-01-15', 120.50, true),
(102, 2, '2023-01-20', 75.00, true),
(103, 1, '2023-02-01', 200.00, false),
(104, 3, '2023-02-05', 50.25, true);

-- 1. Select all active customers
SELECT customer_id, name, email FROM Customers WHERE is_active = true;

-- 2. Find all orders placed by customer_id = 1 that are not yet shipped
SELECT order_id, order_date, total_amount FROM Orders WHERE customer_id = 1 AND is_shipped = false;

-- 3. Calculate the total amount of all orders
SELECT SUM(total_amount) AS total_all_orders FROM Orders;

-- 4. Insert a new customer who is initially inactive
INSERT INTO Customers (customer_id, name, email, is_active) VALUES (4, 'David Lee', 'david@example.com', false);

-- 5. Update a customer's email address and set them as active if they were not
UPDATE Customers SET email = 'alice.s@example.com', is_active = true WHERE customer_id = 1 AND is_active = false;

