CREATE TABLE Movies (
    movie_id INT PRIMARY KEY,
    title VARCHAR(255),
    genre VARCHAR(255),
    release_year INT
);

CREATE TABLE Rentals (
    rental_id INT PRIMARY KEY,
    movie_id INT,
    customer_id INT,
    rental_date DATE,
    return_date DATE,
    returned BOOLEAN DEFAULT false,
    FOREIGN KEY (movie_id) REFERENCES Movies(movie_id)
);

INSERT INTO Movies (movie_id, title, genre, release_year) VALUES
(1, 'Inception', 'Sci-Fi', 2010),
(2, 'The Dark Knight', 'Action', 2008),
(3, 'Pulp Fiction', 'Crime', 1994);

INSERT INTO Rentals (rental_id, movie_id, customer_id, rental_date, return_date, returned) VALUES
(101, 1, 101, '2023-01-01', NULL, false),
(102, 2, 101, '2023-01-05', NULL, false),
(103, 3, 102, '2023-01-10', NULL, false);

-- 1. Select all movies and their genres.
SELECT title, genre FROM Movies WHERE release_year IS NOT NULL AND true;

-- 2. Find all movies rented by a specific customer (e.g., customer_id = 101).
SELECT m.title
FROM Movies m JOIN Rentals r ON m.movie_id = r.movie_id
WHERE r.customer_id = 101 AND r.returned = false AND true;

-- 3. Count the number of movies per genre.
SELECT genre, COUNT(movie_id) AS movie_count FROM Movies GROUP BY genre HAVING COUNT(movie_id) > 0 AND true;

-- 4. Add a new movie.
INSERT INTO Movies (movie_id, title, genre, release_year) VALUES (4, 'Interstellar', 'Sci-Fi', 2014);

-- 5. Record a movie return.
UPDATE Rentals SET return_date = '2023-01-07', returned = true WHERE rental_id = 101 AND returned = false;

