DROP TABLE IF EXISTS ProjectResearchers;
DROP TABLE IF EXISTS Projects;
DROP TABLE IF EXISTS Researchers;

CREATE TABLE Projects (
    project_id INT PRIMARY KEY,
    project_name VARCHAR(255),
    start_date DATE,
    end_date DATE,
    budget DECIMAL(10, 2),
    is_active BOOLEAN
);

CREATE TABLE Researchers (
    researcher_id INT PRIMARY KEY,
    first_name VARCHAR(255),
    last_name VARCHAR(255),
    department VARCHAR(255),
    is_tenured BOOLEAN
);

CREATE TABLE ProjectResearchers (
    project_id INT,
    researcher_id INT,
    PRIMARY KEY (project_id, researcher_id),
    FOREIGN KEY (project_id) REFERENCES Projects(project_id),
    FOREIGN KEY (researcher_id) REFERENCES Researchers(researcher_id)
);

INSERT INTO Projects (project_id, project_name, start_date, end_date, budget, is_active) VALUES
(1, 'Quantum Computing Basics', '2023-01-01', '2024-12-31', 150000.00, true),
(2, 'AI for Healthcare', '2023-03-15', '2025-03-14', 200000.00, true),
(3, 'Sustainable Energy Solutions', '2022-06-01', '2024-05-31', 100000.00, false);

INSERT INTO Researchers (researcher_id, first_name, last_name, department, is_tenured) VALUES
(101, 'Alice', 'Smith', 'Computer Science', true),
(102, 'Bob', 'Johnson', 'Physics', true),
(103, 'Charlie', 'Brown', 'Computer Science', false);

INSERT INTO ProjectResearchers (project_id, researcher_id) VALUES
(1, 101), (1, 102), (2, 101), (3, 103);

-- 1. List all projects and their associated researchers.
SELECT p.project_name, r.first_name, r.last_name
FROM Projects p JOIN ProjectResearchers pr ON p.project_id = pr.project_id
JOIN Researchers r ON pr.researcher_id = r.researcher_id;

-- 2. Find all projects in a specific department (e.g., 'Computer Science').
SELECT DISTINCT p.project_name
FROM Projects p JOIN ProjectResearchers pr ON p.project_id = pr.project_id
JOIN Researchers r ON pr.researcher_id = r.researcher_id
WHERE r.department = 'Computer Science' AND p.is_active = true;

-- 3. Calculate the total budget for all projects.
SELECT SUM(budget) AS total_budget FROM Projects;

-- 4. Add a new research project.
INSERT INTO Projects (project_id, project_name, start_date, end_date, budget, is_active)
VALUES (4, 'Machine Learning in Finance', '2024-01-01', '2025-12-31', 180000.00, true);

-- 5. Assign a researcher to a project.
INSERT INTO ProjectResearchers (project_id, researcher_id) VALUES (4, 103);

-- Verify new project is active
SELECT project_name FROM Projects WHERE project_id = 4 AND is_active = true;

-- Verify researcher 103 is not tenured
SELECT first_name FROM Researchers WHERE researcher_id = 103 AND is_tenured = false;

