DROP TABLE IF EXISTS TrialParticipants;
DROP TABLE IF EXISTS Participants;
DROP TABLE IF EXISTS Trials;

CREATE TABLE Trials (
    trial_id INT PRIMARY KEY,
    trial_name VARCHAR(255),
    start_date DATE,
    end_date DATE,
    is_active BOOLEAN
);

CREATE TABLE Participants (
    participant_id INT PRIMARY KEY,
    first_name VARCHAR(255),
    last_name VARCHAR(255),
    gender VARCHAR(10),
    age INT,
    is_eligible BOOLEAN
);

CREATE TABLE TrialParticipants (
    trial_id INT,
    participant_id INT,
    PRIMARY KEY (trial_id, participant_id),
    FOREIGN KEY (trial_id) REFERENCES Trials(trial_id),
    FOREIGN KEY (participant_id) REFERENCES Participants(participant_id)
);

INSERT INTO Trials (trial_id, trial_name, start_date, end_date, is_active) VALUES
(1, 'Phase 1 Safety Study', '2023-01-01', '2023-06-30', true),
(2, 'Phase 3 Drug Study', '2023-03-15', '2024-03-14', true);

