(101, 'Alice', 'Smith', 'Female', 30, true),
(102, 'Bob', 'Johnson', 'Male', 35, true),
(103, 'Charlie', 'Brown', 'Male', 25, false),
(104, 'Diana', 'Prince', 'Female', 40, true);

