SELECT c.username, ca.cart_id
FROM Customers c
JOIN Carts ca ON c.customer_id = ca.customer_id
WHERE ca.is_checkout_completed = false;

SELECT p.product_name, ci.quantity
FROM Customers cust
JOIN Carts ca ON cust.customer_id = ca.customer_id
JOIN CartItems ci ON ca.cart_id = ci.cart_id
JOIN Products p ON ci.product_id = p.product_id
WHERE cust.customer_id = 1 AND p.is_available = true AND ci.is_item_active = true;

SELECT SUM(ci.quantity * p.price) AS total_value
FROM CartItems ci
JOIN Products p ON ci.product_id = p.product_id
WHERE ci.cart_id = 1001 AND ci.is_item_active = true;

